 @Transactional public InvoiceDetail recalculate(AuthenticatedUser p,long id,SaveInvoice r){var i=accessible(p,id,true);write(p);capability(p,"can_issue_invoice");if(!"DRAFT".equals(i.get("status"))||r.version()==null||r.version()!=l(i,"version")||r.contractId()!=l(i,"contract_id")||r.roomId()!=l(i,"room_id")||!LocalDate.parse(r.billingPeriod()+"-01").equals(date(i,"billing_period")))throw conflict();if(r.note()==null||r.note().isBlank())throw bad("REVISION_REASON_REQUIRED","Cần lý do tính lại bản nháp.");validateDates(r);var c=repo.contractForRoom(r.roomId(),r.contractId()).orElseThrow();var plan=repo.calculate(r,c);BigDecimal subtotal=plan.items().stream().map(com.thangit.boardinghouse.service.MonthlyBillingService.Charge::amount).reduce(BigDecimal.ZERO,BigDecimal::add);if(nvl(r.discountAmount()).compareTo(subtotal)>0)throw bad("INVOICE_DISCOUNT_INVALID","Giảm giá vượt tổng tiền.");repo.recalculate(id,r,subtotal,plan);repo.history(id,"DRAFT_RECALCULATED","DRAFT","DRAFT",r.note(),p.id());return detail(p,id);}
