 @Override @Transactional(readOnly=true) public InvoiceDetail detail(AuthenticatedUser p,long id){Map<String,Object> i=accessible(p,id,false);String status=effective(i);boolean draft="DRAFT".equals(status),cancelled="CANCELLED".equals(status),paid="PAID".equals(status);boolean write=canWrite(p);return new InvoiceDetail(id,s(i,"code"),period(date(i,"billing_period")),date(i,"period_start_date"),date(i,"period_end_date"),date(i,"issue_date"),date(i,"due_date"),status,new Party(l(i,"property_id"),s(i,"property_name"),s(i,"property_address")),new Party(l(i,"room_id"),s(i,"room_code"),s(i,"building_name")+" · "+s(i,"floor_name")),new Party(l(i,"tenant_id"),s(i,"tenant_name"),s(i,"tenant_phone")),new Party(l(i,"contract_id"),s(i,"contract_code"),null),repo.items(id),money(i,"subtotal_amount"),money(i,"discount_amount"),money(i,"previous_debt_amount"),money(i,"late_fee_amount"),money(i,"total_amount"),money(i,"paid_amount"),money(i,"remaining_amount"),s(i,"note"),repo.payments(id),repo.adjustments(id),repo.notifications(id),repo.history(id),new Permissions(write&&draft,write&&draft,write&&!draft&&!cancelled&&!paid,write&&!draft&&!cancelled,write&&!draft&&!cancelled,write&&!cancelled&&money(i,"paid_amount").signum()==0,true,true),l(i,"version"));}
 @Override @Transactional public CreateResult create(AuthenticatedUser p,SaveInvoice r){write(p);capability(p,"can_issue_invoice");validateDates(r);Map<String,Object> c=repo.contractForRoom(r.roomId(),r.contractId()).orElseThrow(()->bad("INVOICE_CONTRACT_INVALID","Hợp đồng không thuộc phòng đã chọn."));long propertyId=l(c,"property_id");property(p,propertyId);LocalDate period=LocalDate.parse(r.billingPeriod()+"-01");if(repo.duplicate(r.contractId(),period,null))throw bad("INVOICE_PERIOD_EXISTS","Hóa đơn cho phòng và kỳ này đã tồn tại.");return createCalculated(p,r,c,period,false);}
 private CreateResult createCalculated(AuthenticatedUser p,SaveInvoice r,Map<String,Object> c,LocalDate period,boolean automated){repo.managerCapability(p,l(c,"property_id"),"FINANCE_WRITE");if(c.get("monthly_rent")==null)throw bad("CONTRACT_RENT_RECONCILIATION_REQUIRED","Contract agreed rent requires reconciliation.");var plan=repo.calculate(r,c);List<CalcItem> items=plan.items().stream().map(x->new CalcItem(x.type(),x.name(),x.description(),x.quantity(),x.unit(),x.price(),x.amount(),x.source(),x.sourceId())).toList();int order=1;BigDecimal subtotal=items.stream().map(CalcItem::amount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal discount=nvl(r.discountAmount());if(discount.compareTo(subtotal)>0)throw bad("INVOICE_DISCOUNT_INVALID","Giảm giá không được vượt quá tổng khoản thu.");BigDecimal debt=r.includePreviousDebt()?repo.previousDebt(r.contractId(),period):BigDecimal.ZERO;BigDecimal total=subtotal.subtract(discount);String status="ISSUE".equals(r.action())?"ISSUED":"DRAFT";String code="HD-"+r.billingPeriod().replace("-","")+"-"+java.util.UUID.randomUUID().toString().replace("-","");long id=repo.createInvoice(l(c,"property_id"),r.roomId(),r.contractId(),l(c,"tenant_id"),code,period,r.periodStartDate(),r.periodEndDate(),r.issueDate(),r.dueDate(),subtotal,discount,debt,BigDecimal.ZERO,total,status,r.note(),p.id(),automated);for(CalcItem x:items)repo.addItem(id,x.type(),x.type(),x.name(),x.description(),x.quantity(),x.unit(),x.price(),x.amount(),x.source(),x.sourceId(),order++);repo.snapshot(id,plan.content(),plan.hash());if(!"DRAFT".equals(status))repo.notifyIssued(id);repo.history(id,"DRAFT".equals(status)?"CREATED_DRAFT":"CREATED_AND_ISSUED",null,status,null,p.id());return new CreateResult(id,code,status);}
 private void addUtility(List<CalcItem> items,Map<String,Object> u,String type,String name,String prev,String current,String price,String amount,String unit){BigDecimal a=money(u,amount);if(a.signum()>0){BigDecimal qty=money(u,current).subtract(money(u,prev));items.add(new CalcItem(type,name,"Chỉ số "+money(u,prev)+" → "+money(u,current),qty,unit,money(u,price),a,"UTILITY_READING",l(u,"id")));}}
