 @Override @Transactional public InvoiceDetail issue(AuthenticatedUser p,long id,long version){Map<String,Object>i=accessible(p,id,true);write(p);capability(p,"can_issue_invoice");repo.validateIssue(i);if(repo.issue(id,p.id(),version)==0)throw conflict();repo.history(id,"ISSUED",s(i,"status"),"ISSUED",null,p.id());repo.notifyIssued(id);return detail(p,id);}
 @Override @Transactional public InvoiceDetail payment(AuthenticatedUser p,long id,String key,RecordPayment r){
  write(p);capability(p,"can_record_payment");if(key==null||key.isBlank()||key.length()>100)throw bad("IDEMPOTENCY_KEY_REQUIRED","Cần Idempotency-Key hợp lệ để tránh ghi nhận thanh toán trùng.");String normalizedKey=key.trim();
  Map<String,Object>prior=repo.paymentByKey(normalizedKey).orElse(null);if(prior!=null){samePayment(prior,id,r);return detail(p,id);}
  Map<String,Object>i=accessible(p,id,true);prior=repo.paymentByKey(normalizedKey).orElse(null);if(prior!=null){samePayment(prior,id,r);return detail(p,id);}
  long propertyId=l(i,"property_id");BigDecimal remaining=money(i,"remaining_amount");
  if(List.of("DRAFT","PENDING_REVIEW","CANCELLED","PAID").contains(s(i,"status")))throw conflict("INVOICE_NOT_PAYABLE","Hóa đơn không ở trạng thái có thể thanh toán.");
  if(repo.accountingPeriodLocked(propertyId,r.paidAt().toLocalDate()))throw bad("ACCOUNTING_PERIOD_CLOSED","Không thể ghi nhận thanh toán trong kỳ kế toán đã khóa.");
  if(r.amount().compareTo(remaining)>0)throw bad("PAYMENT_EXCEEDS_DEBT","Số tiền thanh toán vượt quá công nợ.");
  if(r.amount().compareTo(remaining)<0&&!repo.allowPartial(propertyId))throw bad("PARTIAL_PAYMENT_DISABLED","Chính sách của chủ trọ yêu cầu thanh toán toàn bộ số tiền còn lại.");
  repo.lockPaymentScope(propertyId);if(r.referenceCode()!=null&&!r.referenceCode().isBlank()&&repo.paymentByReference(propertyId,r.paymentMethod(),r.referenceCode()).isPresent())throw conflict("PAYMENT_REFERENCE_DUPLICATE","Mã tham chiếu đã được ghi nhận cho cùng tài khoản nhận tiền.");
  long paymentId;try{paymentId=repo.payment(i,r.amount(),r.paymentMethod(),r.paidAt(),r.referenceCode(),r.note(),normalizedKey,p.id());}catch(DuplicateKeyException e){prior=repo.paymentByKey(normalizedKey).orElse(null);if(prior==null&&r.referenceCode()!=null&&!r.referenceCode().isBlank())throw conflict("PAYMENT_REFERENCE_DUPLICATE","Mã tham chiếu đã được ghi nhận cho khu trọ này.");if(prior==null)throw conflict("PAYMENT_DUPLICATE","Giao dịch đã tồn tại.");samePayment(prior,id,r);return detail(p,id);}
  long version=r.version()==null?l(i,"version"):r.version();if(repo.applyPayment(id,r.amount(),version)==0)throw conflict();repo.receipt(paymentId,i,r.amount(),p.id(),r.note());repo.audit(propertyId,p.id(),paymentId,"CONFIRMED","Phân bổ vào hóa đơn "+s(i,"code"));repo.notifyPayment(i,r.amount());repo.history(id,"PAYMENT_RECORDED",s(i,"status"),r.amount().compareTo(remaining)==0?"PAID":"PARTIALLY_PAID",null,p.id());return detail(p,id);
 }
 @Override @Transactional public InvoiceDetail cancel(AuthenticatedUser p,long id,CancelInvoice r){Map<String,Object>i=accessible(p,id,true);write(p);capability(p,"can_create_adjustment");if(repo.accountingPeriodLocked(l(i,"property_id"),date(i,"billing_period")))throw bad("ACCOUNTING_PERIOD_CLOSED","Kỳ kế toán đã khóa.");long v=r.version()==null?l(i,"version"):r.version();if(repo.cancel(id,r.reason(),p.id(),v)==0)throw bad("INVOICE_CANNOT_CANCEL","Không thể hủy hóa đơn đã thanh toán hoặc dữ liệu đã thay đổi.");repo.history(id,"CANCELLED",s(i,"status"),"CANCELLED",r.reason(),p.id());return detail(p,id);}
 @Override @Transactional public InvoiceDetail adjust(AuthenticatedUser p,long id,Adjustment r){Map<String,Object>i=accessible(p,id,true);write(p);capability(p,"can_create_adjustment");if(repo.accountingPeriodLocked(l(i,"property_id"),date(i,"billing_period")))throw bad("ACCOUNTING_PERIOD_CLOSED","Kỳ kế toán đã khóa.");if(r.version()!=null&&r.version()!=l(i,"version"))throw conflict();long v=r.version()==null?l(i,"version"):r.version();if(repo.adjust(id,r.adjustmentType(),r.amount(),r.reason(),p.id(),v)==0)throw bad("ADJUSTMENT_INVALID","Khoản điều chỉnh không hợp lệ hoặc dữ liệu đã thay đổi.");repo.history(id,"ADJUSTED",s(i,"status"),s(i,"status"),r.reason(),p.id());return detail(p,id);}
 @Override @Transactional public InvoiceDetail reminder(AuthenticatedUser p,long id,Reminder r){Map<String,Object>i=accessible(p,id,false);write(p);if(!"IN_APP".equals(r.channel()))throw new AuthException(HttpStatus.SERVICE_UNAVAILABLE,"NOTIFICATION_CHANNEL_UNAVAILABLE","External notification delivery is not configured.");String recipient=Long.toString(l(i,"tenant_id"));repo.reminder(id,r.channel(),recipient,p.id());repo.history(id,"REMINDER_SENT",s(i,"status"),s(i,"status"),r.channel(),p.id());return detail(p,id);}
 @Override @Transactional(readOnly=true) public byte[] export(AuthenticatedUser p,Long propertyId,String period,String status){read(p);repo.requireExport(p,propertyId);StringBuilder out=new StringBuilder("\uFEFFMã hóa đơn,Kỳ,Nhà trọ,Phòng,Người thuê,Tổng tiền,Đã thu,Còn lại,Trạng thái\n");for(int exportPage=0;;exportPage++){var page=list(p,propertyId,null,null,null,null,period,status,null,null,null,"newest",exportPage,100);for(InvoiceRow r:page.content())out.append(csv(r.invoiceCode())).append(',').append(csv(r.billingPeriod())).append(',').append(csv(r.property().name())).append(',').append(csv(r.room().name())).append(',').append(csv(r.tenant().name())).append(',').append(r.totalAmount()).append(',').append(r.paidAmount()).append(',').append(r.remainingAmount()).append(',').append(r.status()).append('\n');if(page.content().size()<100)break;}return out.toString().getBytes(StandardCharsets.UTF_8);}
