 private Map<String,Object> accessible(AuthenticatedUser p,long id,boolean lock){read(p);Map<String,Object>i=repo.invoice(id,lock).orElseThrow(()->new AuthException(HttpStatus.NOT_FOUND,"INVOICE_NOT_FOUND","Không tìm thấy hóa đơn."));property(p,l(i,"property_id"));if(lock)repo.managerCapability(p,l(i,"property_id"),"FINANCE_WRITE");return i;}
 private void validateDates(SaveInvoice r){if(r.periodEndDate().isBefore(r.periodStartDate()))throw bad("INVOICE_PERIOD_INVALID","Ngày kết thúc kỳ phải sau ngày bắt đầu.");if(r.dueDate().isBefore(r.issueDate()==null?LocalDate.now():r.issueDate()))throw bad("INVOICE_DUE_DATE_INVALID","Hạn thanh toán không được trước ngày lập.");}
 private void read(AuthenticatedUser p){if(p==null||!List.of(RoleCode.OWNER,RoleCode.MANAGER,RoleCode.ACCOUNTANT).contains(p.activeRole()))throw new AuthException(HttpStatus.FORBIDDEN,"INVOICE_ACCESS_DENIED","Bạn không có quyền truy cập hóa đơn quản trị.");}private void write(AuthenticatedUser p){read(p);if(!canWrite(p))throw new AuthException(HttpStatus.FORBIDDEN,"INVOICE_WRITE_DENIED","Bạn không có quyền thay đổi hóa đơn.");}private boolean canWrite(AuthenticatedUser p){return List.of(RoleCode.OWNER,RoleCode.MANAGER,RoleCode.ACCOUNTANT).contains(p.activeRole());}private void property(AuthenticatedUser p,long id){if(!repo.canAccess(p.id(),p.activeRole(),id))throw new AuthException(HttpStatus.FORBIDDEN,"INVOICE_PROPERTY_DENIED","Bạn không có quyền với khu trọ này.");}
 private void samePayment(Map<String,Object> prior,long invoiceId,RecordPayment r){boolean same=l(prior,"invoice_id")==invoiceId&&money(prior,"amount").compareTo(r.amount())==0&&Objects.equals(s(prior,"payment_method"),r.paymentMethod())&&Objects.equals(clean(s(prior,"reference_code")),clean(r.referenceCode()))&&Objects.equals(clean(s(prior,"note")),clean(r.note()))&&Objects.equals(micros(time(prior,"paid_at")),micros(r.paidAt()));if(!same)throw conflict("IDEMPOTENCY_KEY_REUSED","Idempotency-Key đã được dùng với nội dung thanh toán khác.");}
 private String effective(Map<String,Object>i){String st=s(i,"status");return !"CANCELLED".equals(st)&&!"PAID".equals(st)&&!"DRAFT".equals(st)&&money(i,"remaining_amount").signum()>0&&date(i,"due_date").isBefore(LocalDate.now())?"OVERDUE":st;}private AuthException bad(String c,String m){return new AuthException(HttpStatus.BAD_REQUEST,c,m);}private AuthException conflict(){return conflict("INVOICE_VERSION_CONFLICT","Hóa đơn đã được người khác cập nhật. Vui lòng tải lại.");}private AuthException conflict(String c,String m){return new AuthException(HttpStatus.CONFLICT,c,m);}
 private record CalcItem(String type,String name,String description,BigDecimal quantity,String unit,BigDecimal price,BigDecimal amount,String source,Long sourceId){}
 private static String s(Map<String,Object>m,String k){return m.get(k)==null?null:m.get(k).toString();}private static long l(Map<String,Object>m,String k){return ((Number)m.get(k)).longValue();}private static BigDecimal money(Map<String,Object>m,String k){Object x=m.get(k);return x==null?BigDecimal.ZERO:x instanceof BigDecimal b?b:new BigDecimal(x.toString());}private static BigDecimal nvl(BigDecimal x){return x==null?BigDecimal.ZERO:x;}private static LocalDate date(Map<String,Object>m,String k){Object x=m.get(k);if(x==null)return null;if(x instanceof LocalDate d)return d;if(x instanceof Date d)return d.toLocalDate();return ((Timestamp)x).toLocalDateTime().toLocalDate();}private static LocalDateTime time(Map<String,Object>m,String k){Object x=m.get(k);if(x instanceof LocalDateTime d)return d;if(x instanceof Timestamp t)return t.toLocalDateTime();return null;}private static LocalDateTime micros(LocalDateTime x){return x==null?null:x.withNano((x.getNano()/1000)*1000);}private static String clean(String x){return x==null||x.isBlank()?null:x.trim();}private static String period(LocalDate x){return "%02d/%d".formatted(x.getMonthValue(),x.getYear());}private static String csv(String x){return com.thangit.boardinghouse.common.validation.CsvCells.quote(x);}
 private static byte[] minimalPdf(String value){String safe=value.replaceAll("[^\\x20-\\x7E]","?").replace("(","[").replace(")","]");String stream="BT /F1 12 Tf 50 760 Td ("+safe+") Tj ET";String[]o={"1 0 obj<< /Type /Catalog /Pages 2 0 R >>endobj\n","2 0 obj<< /Type /Pages /Kids [3 0 R] /Count 1 >>endobj\n","3 0 obj<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>endobj\n","4 0 obj<< /Length "+stream.length()+" >>stream\n"+stream+"\nendstream endobj\n","5 0 obj<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>endobj\n"};StringBuilder b=new StringBuilder("%PDF-1.4\n");int[]pos=new int[6];for(int i=0;i<o.length;i++){pos[i+1]=b.length();b.append(o[i]);}int x=b.length();b.append("xref\n0 6\n0000000000 65535 f \n");for(int i=1;i<=5;i++)b.append(String.format("%010d 00000 n \n",pos[i]));b.append("trailer<< /Size 6 /Root 1 0 R >>\nstartxref\n").append(x).append("\n%%EOF");return b.toString().getBytes(StandardCharsets.US_ASCII);}
